if (document.getElementById('glb-feed-toggle-btn')) return;

// --- Inject styles ---
const style = document.createElement('style');
style.id = 'glb-feed-toggle-styles';
style.textContent = `
  #glb-feed-toggle-btn {
    position: fixed;
    bottom: 28px;
    right: 28px;
    z-index: 99999;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 11px 20px;
    background: #003087;
    color: #fff;
    border: none;
    border-radius: 50px;
    font-family: sans-serif;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.3px;
    cursor: pointer;
    box-shadow: 0 4px 18px rgba(0,0,0,0.28);
    transition: background 0.2s, transform 0.15s;
    user-select: none;
  }
  #glb-feed-toggle-btn:hover { background: #0040b8; transform: translateY(-2px); }
  #glb-feed-toggle-btn svg { flex-shrink: 0; }

  /* ── FOCUS MODE styles ── */
  body.glb-focus-mode .post-column-1,
  body.glb-focus-mode .post-column-2 {
    display: none !important;
  }
  body.glb-focus-mode #widget-economia,
  body.glb-focus-mode #widget-sports,
  body.glb-focus-mode .widget-horoscopo,
  body.glb-focus-mode .widget-sports {
    display: none !important;
  }
  body.glb-focus-mode .area-destaque .post-row {
    display: flex !important;
    flex-direction: column !important;
    width: 100% !important;
  }
  body.glb-focus-mode .area-destaque .post-row .wrapper {
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box;
  }
  body.glb-focus-mode .area-colunas__container {
    display: flex !important;
    flex-direction: column !important;
    gap: 0 !important;
  }
  body.glb-focus-mode .column-container-jornalismo,
  body.glb-focus-mode .column-container-esporte,
  body.glb-focus-mode .column-container-entretenimento {
    width: 100% !important;
    max-width: 760px !important;
    margin: 0 auto !important;
    box-sizing: border-box;
  }
  body.glb-focus-mode .area-colunas {
    max-width: 780px !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }
  body.glb-focus-mode .highlight-container .area-destaque {
    display: flex !important;
    flex-direction: column !important;
    gap: 0 !important;
  }
  body.glb-focus-mode .highlight-container .headline {
    width: 100% !important;
    max-width: 760px !important;
    margin: 0 auto !important;
  }
  body.glb-focus-mode .post__title {
    font-size: 1.05em !important;
  }
`;
document.head.appendChild(style);

// --- Create button ---
const btn = document.createElement('button');
btn.id = 'glb-feed-toggle-btn';

const iconGrid = `<svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="1" y="1" width="7" height="7" rx="1.2" fill="white"/><rect x="10" y="1" width="7" height="7" rx="1.2" fill="white"/><rect x="1" y="10" width="7" height="7" rx="1.2" fill="white"/><rect x="10" y="10" width="7" height="7" rx="1.2" fill="white"/></svg>`;
const iconFeed = `<svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="2" width="14" height="3" rx="1.2" fill="white"/><rect x="2" y="7.5" width="14" height="3" rx="1.2" fill="white"/><rect x="2" y="13" width="14" height="3" rx="1.2" fill="white"/></svg>`;

function updateBtn() {
  const isActive = document.body.classList.contains('glb-focus-mode');
  btn.innerHTML = isActive
    ? iconGrid + ' Modo Original'
    : iconFeed + ' Feed Linear';
}

btn.addEventListener('click', function() {
  document.body.classList.toggle('glb-focus-mode');
  updateBtn();
});

updateBtn();
document.body.appendChild(btn);
